cpp.setup:
auto* layout = new QVBoxLayout(%PARENT%);
layout->setContentsMargins(16, 12, 16, 14);
layout->setSpacing(0);
auto* control = new fluent::status_info::ToolTip(%PARENT%);
control->setWindowFlags(Qt::Widget);
auto policy = control->sizePolicy();
policy.setRetainSizeWhenHidden(true);
control->setSizePolicy(policy);
control->setAnimationEnabled(false);
control->show();
control->setAnimationEnabled(true);
auto* anchor = new fluent::basicinput::Button(QStringLiteral("Archive"), %PARENT%);
anchor->setFixedSize(112, 32);
QObject::connect(anchor, &fluent::basicinput::Button::clicked, control, [control] {
    control->setVisible(!control->isVisible());
});
layout->addStretch(1);
layout->addWidget(control, 0, Qt::AlignHCenter);
layout->addWidget(anchor, 0, Qt::AlignHCenter);
layout->addStretch(1);
